/**
 * To easily test if your release will apply locally, you can run:
 * yarn test-npm-package-release-script
 */
const execa = require('execa')
const fs = require('fs')
const semverSortNewestFirst = require('semver/functions/rcompare')
const SENTINEL_VERSION = '0.0.0-development'
const checkedInBinaryVersion = require('../package.json').version

const { getCurrentBranch, getPackagePath, readPackageJson, independentTagRegex } = require('./utils')

const error = (message) => {
  if (require.main === module) {
    console.error(`\nERROR!`)
    console.error(message)

    process.exit(1)
  } else {
    throw new Error(message)
  }
}

const getTags = async () => {
  const { stdout } = await execa('git', ['tag', '--merged', await getCurrentBranch()])

  return stdout.split('\n')
}

const parseSemanticReleaseOutput = (output) => {
  const currentVersion = (output.match(/associated with version (\d+\.\d+\.\d+-?\S*)/) || [])[1]
  const nextVersion = (output.match(/next release version is (\d+\.\d+\.\d+-?\S*)/) || [])[1]

  return {
    currentVersion,
    nextVersion,
  }
}

// in addition to getting the next version that's going to be released
// this serves as a good double check that the release will work before we actually do it
const getNextVersion = async (name) => {
  // we cannot use the semantic-release javascript api
  // since it will break semantic-release-monorepo plugin
  const { stdout } = await execa('npx', ['lerna', 'exec', '--scope', name, '--', 'npx', '--no-install', 'semantic-release', '--dry-run'])

  return parseSemanticReleaseOutput(stdout).nextVersion
}

// we manually check the last version on this branch as opposed to what semantic-release says
// since semantic-release may be not be configured on the current branch for a package
const getCurrentVersion = async (name) => {
  const tags = await getTags()

  const versions = tags
  .map((tag) => (tag.match(independentTagRegex(name)) || [])[1])
  .filter((tag) => tag)
  .sort(semverSortNewestFirst)

  return versions[0]
}

const getPackageVersions = async (packages) => {
  console.log(`Finding package versions...\n`)

  // If package.json still carries the sentinel (i.e. get-next-version --npm hasn't
  // stamped the real version yet), compute it now so injectVersions can substitute
  // the correct version into any dependency that lists cypress as "0.0.0-development".
  let binaryVersion = checkedInBinaryVersion

  if (binaryVersion === SENTINEL_VERSION) {
    binaryVersion = require('child_process')
    .execSync('node ./scripts/get-next-version.js')
    .toString()
    .trim()
  }

  console.log(`Cypress binary: ${binaryVersion}`)

  const versions = {
    cypress: {
      currentVersion: binaryVersion,
      nextVersion: undefined,
    },
  }

  for (const name of packages) {
    console.log(`\n${name}`)

    const currentVersion = await getCurrentVersion(name)
    const nextVersion = await getNextVersion(name)

    console.log(`Current version: ${currentVersion || 'N/A'}`)
    console.log(`Next version: ${nextVersion || 'N/A'}`)

    versions[name] = {
      currentVersion,
      nextVersion,
    }
  }

  return versions
}

// updates a public package's package.json
// replaces any local dependencies that have a * version
// with the actual numbered version of that dependency
// if that dependency is also going to be released from this run
// it updates with the new version
const injectVersions = (packagesToRelease, versions, packages) => {
  console.log('\nInjecting versions into package.json files...')

  for (const name of packagesToRelease) {
    console.log(`\nUpdating package.json of ${name}`)

    const info = packages.find((p) => p.name === name)
    const packageJson = readPackageJson(info)

    if (packageJson.dependencies) {
      for (const dependency in packageJson.dependencies) {
        if (packageJson.dependencies[dependency] === '0.0.0-development' || packageJson.dependencies[dependency] === '*') {
          const version = versions[dependency].nextVersion || versions[dependency].currentVersion

          if (!version) {
            return error(`Could not inject a version for ${dependency} since it has no current or next version`)
          }

          packageJson.dependencies[dependency] = version

          console.log(`\t${dependency}: ${version}`)
        }
      }

      fs.writeFileSync(getPackagePath(info), JSON.stringify(packageJson, null, 2))
    }
  }
}

const releasePackages = async (packages) => {
  console.log(`\nReleasing packages`)

  let failures = []

  // it would make sense to run each release simultaneously with something like Promise.all()
  // however this can cause a race condition within git (git lock throws an error)
  // so we run them one by one to avoid this
  for (const name of packages) {
    console.log(`\nReleasing ${name}...`)
    // semantic-release v19 upgraded to npm v8 which supports workspaces. When
    // running semantic-release, npm thinks that our lerna workspace is an npm
    // workspace. When npm executes commands that modify the workspace, it will
    // check the validity of the workspace. We don't want this to happen since
    // since we don't use npm and our links/peerDependencies make npm unhappy.
    // We disable the workspace update via the NPM_CONFIG_WORKSPACES_UPDATE=false
    // env variable.
    try {
      const { stdout } = await execa(
        'npx',
        ['lerna', 'exec', '--scope', name, '--', 'npx', '--no-install', 'semantic-release'],
        { env: { NPM_CONFIG_WORKSPACES_UPDATE: false } },
      )

      console.log(`Released ${name} successfully:`)
      console.log(stdout)
    } catch (err) {
      failures.push(name)

      console.log(`Releasing ${name} failed:`)
      console.log(err.stack)
    }
  }

  if (failures.length) {
    console.log(`\nThe following packages failed to release:\n- ${failures.join('\n- ')}`)
  } else {
    console.log(`\nAll packages released successfully`)
  }

  return failures.length
}

const getLernaPackages = async () => {
  const { stdout } = await execa('npx', ['lerna', 'la', '--json'])

  return JSON.parse(stdout)
}

// goes through the release process for all of our independent npm projects
const main = async () => {
  // in case no NPM_TOKEN is provided (running a simulation locally),
  // make up a fake one to avoid semantic-release breaking
  if (!process.env.CIRCLECI && !process.env.NPM_TOKEN) {
    process.env.NPM_TOKEN = 1
  }

  const packages = await getLernaPackages()
  const publicPackages = packages
  .filter((pkg) => !pkg.private && !pkg.name.includes('@packages'))
  .map((pkg) => pkg.name)

  console.log(`Found the following public packages: ${publicPackages.join(', ')}\n`)

  const versions = await getPackageVersions(publicPackages)
  const packagesToRelease = Object.keys(versions).filter((key) => versions[key].nextVersion)

  console.log(`\nFound a new release for the following packages: ${packagesToRelease.join(', ')}`)

  if (!packagesToRelease.length) {
    return console.log(`\nThere are no packages to release!`)
  }

  injectVersions(packagesToRelease, versions, packages)

  if (!process.env.CIRCLECI) {
    return error(`Cannot run release process outside of Circle CI`)
  }

  if (process.env.CIRCLE_PULL_REQUEST) {
    return console.log(`Release process cannot be run on a PR`)
  }

  const numFailures = await releasePackages(packagesToRelease)

  if (numFailures) {
    process.exit(numFailures)
  } else {
    console.log(`\n\nRelease process completed successfully!`)
  }
}

// execute main function if called from command line
if (require.main === module) {
  main()
}

module.exports = {
  parseSemanticReleaseOutput,
  readPackageJson,
  releasePackages,
}

const minimist = require('minimist')
const { execSync } = require('child_process')

const args = minimist(process.argv.slice(2))

if (!/^[a-z0-9]{40}$/.test(args.sha)) {
  throw new Error('A valid (40 character) commit SHA must be passed in `--sha`.')
}

if (!/^\d+\.\d+\.\d+$/.test(args.version)) {
  throw new Error('A valid semantic version (X.Y.Z) must be passed in `--version`.')
}

const log = (...args) => console.log('🏗', ...args)

const exec = args['dry-run'] ?
  (...args) => log('Dry run, not executing:', args[0])
  : (...args) => execSync(...args)

log('Running `move-binaries`...')
exec(`node ./scripts/binary.js move-binaries --sha ${args.sha} --version ${args.version}`, { stdio: 'inherit' })

const prereleaseNpmUrl = `https://cdn.cypress.io/beta/npm/${args.version}/linux-x64/develop-${args.sha}/cypress.tgz`

log('Running `create-stable-npm-package`...')
exec(`./scripts/create-stable-npm-package.sh ${prereleaseNpmUrl}`, { stdio: 'inherit' })

import _ from 'lodash'
import path from 'path'
import shell from 'shelljs'
import fs from 'fs-extra'

// grab the current version and a few other properties
// from the root package.json
import rootPkg from '@packages/root'

const {
  version,
  description,
  homepage,
  license,
  bugs,
  repository,
  keywords,
} = rootPkg as any

// the rest of properties should come from the package.json in CLI folder
const packageJsonSrc = path.join('package.json')
const packageJsonDest = path.join('build', 'package.json')

function getStdout (cmd: string): string {
  return shell.exec(cmd).trim()
}

function preparePackageForNpmRelease (json: any, branchName?: string): any {
  // modify the existing package.json
  // to prepare it for releasing to npm
  delete json.devDependencies
  delete json['private']
  // no need to include "nyc" code coverage settings
  delete json.nyc
  delete json.workspaces

  _.extend(json, {
    version,
    buildInfo: {
      commitBranch: branchName || process.env.CIRCLE_BRANCH || getStdout('git branch --show-current'),
      commitSha: getStdout('git rev-parse HEAD'),
      commitDate: new Date(getStdout('git show -s --format=%ci')).toISOString(),
      stable: false,
    },
    // @packages/ dependencies are internal, and included in the cli bundle via rollup
    ...(json.dependencies ? { dependencies: Object.fromEntries(
      Object.entries(json.dependencies || {})
      .filter(([key]) => !key.startsWith('@packages/')),
    ) } : {}),
    description,
    homepage,
    license,
    bugs,
    repository,
    keywords,
    types: 'types', // typescript types
    scripts: {
      postinstall: 'node dist/index.js --exec install',
      size: 't="$(npm pack .)"; wc -c "${t}"; tar tvf "${t}"; rm "${t}";',
    },
  })

  return json
}

async function makeUserPackageFile (branchName?: string): Promise<any> {
  const json = await fs.readJson(packageJsonSrc)
  const jsonPrepared = preparePackageForNpmRelease(json, branchName)

  await fs.outputJson(packageJsonDest, jsonPrepared, {
    spaces: 2,
  }) // returning package json object makes it easy to test

  return jsonPrepared
}

export default makeUserPackageFile

if (require.main === module) {
  makeUserPackageFile(process.env.BRANCH)
  .catch((err: any) => {
    console.error('Could not write user package file')
    console.error(err)

    process.exit(-1)
  })
}

require('../packages/ts/register')

const command = process.argv[2]

if (!command) {
  console.error('Missing deploy command ⛔️')
  process.exit(1)
}

const commands = require('./binary/index')
const fn = commands[command]

if (!fn) {
  console.error('Invalid deploy command %s 🚫', command)
}

// TODO allow passing CLI arguments to each command

fn()
.then(() => {
  return console.log('✅ %s completed', command)
})
.catch((err) => {
  console.error('🔥 deploy error')
  console.error(err)
  process.exit(1)
})

const path = require('path')
const semver = require('semver')
const bumpCb = require('conventional-recommended-bump')
const { promisify } = require('util')
const minimist = require('minimist')

const checkedInBinaryVersion = require('../package.json').version
const SENTINEL_VERSION = '0.0.0-development'
const isSentinelVersion = checkedInBinaryVersion === SENTINEL_VERSION
const { changeCatagories } = require('./semantic-commits/change-categories')
const { getCurrentReleaseData } = require('./semantic-commits/get-current-release-data')

const bump = promisify(bumpCb)
const paths = ['packages', 'cli']

const getNextVersionForPath = async (path) => {
  const { version: releasedVersion } = await getCurrentReleaseData(false)

  let commits
  const whatBump = (foundCommits) => {
    // semantic version bump: 0 - major, 1 - minor, 2 - patch
    let level = 2
    let breakings = 0
    let features = 0

    commits = foundCommits
    foundCommits.forEach((commit) => {
      if (!commit.type || !changeCatagories[commit.type]) return

      if (changeCatagories[commit.type].release === 'major') {
        breakings += 1
        level = 0
      } else if (changeCatagories[commit.type].release === 'minor') {
        features += 1
        if (level === 2) {
          level = 1
        }
      }
    })

    return {
      level,
      reason: breakings > 0
        ? `There is ${breakings} BREAKING CHANGE and ${features} features`
        : features > 0 ? `There ${features} features` : 'There are only patch changes in this release',
    }
  }

  const { releaseType } = await bump({
    whatBump,
    path,
  })

  let nextVersion = semver.inc(releasedVersion, releaseType || 'patch')

  // See ../guides/next-version.md for documentation.
  // for the time being, honoring this ENV -- ideally this will be deleted to remove manually overriding without a PR
  if (process.env.NEXT_VERSION) {
    nextVersion = process.env.NEXT_VERSION
  } else if (!isSentinelVersion && checkedInBinaryVersion !== releasedVersion) {
    // honor a manually-set real version in package.json
    nextVersion = checkedInBinaryVersion
  }

  return {
    nextVersion,
    commits,
  }
}

const getNextVersionForBinary = async () => {
  let commits = []
  let nextVersion

  for (const path of paths) {
    const { nextVersion: pathNextVersion, commits: pathCommits } = await getNextVersionForPath(path)

    if (!nextVersion || semver.gt(pathNextVersion, nextVersion)) {
      nextVersion = pathNextVersion
    }

    commits = commits.concat(pathCommits)
  }

  if (!nextVersion) {
    throw new Error('Unable to determine next version.')
  }

  return {
    nextVersion,
    commits,
  }
}

if (require.main !== module) {
  module.exports = {
    getNextVersionForBinary,
    getNextVersionForPath,
  }

  return
}

(async () => {
  process.chdir(path.join(__dirname, '..'))

  const args = minimist(process.argv.slice(2))

  const nextVersion = args.nextVersion || (await getNextVersionForBinary()).nextVersion

  if (args.npm && checkedInBinaryVersion !== nextVersion) {
    const cmd = `npm --no-git-tag-version version ${nextVersion}`

    console.log(`Running '${cmd}'...`)

    return require('child_process').execSync(cmd)
  }

  console.log(nextVersion)
})()

